/* First-person crosshair */
.crosshair {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 20px;
  height: 20px;
  transform: translate(-50%, -50%);
  pointer-events: none;
  z-index: 4;
  opacity: 0.75;
}
.crosshair::before, .crosshair::after {
  content: '';
  position: absolute;
  background: #d8ff5f;
  box-shadow: 0 0 10px #d8ff5f;
  border-radius: 1px;
}
.crosshair::before { left: 9px; top: 0; width: 2px; height: 10px; }
.crosshair::after { top: 9px; left: 0; width: 10px; height: 2px; }

